struct sha256_state {
  uint32_t h[8];
  uint64_t bytes;
  unsigned char block[64];
  size_t used;
};

static uint32_t ror32(uint32_t value, unsigned count) {
  return (value >> count) | (value << (32U - count));
}

static uint32_t load_be32(const unsigned char *p) {
  return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static void store_be32(unsigned char *p, uint32_t value) {
  p[0] = (unsigned char)(value >> 24); p[1] = (unsigned char)(value >> 16);
  p[2] = (unsigned char)(value >> 8); p[3] = (unsigned char)value;
}

static void sha256_compress(struct sha256_state *state, const unsigned char block[64]) {
  static const uint32_t k[64] = {
    0x428a2f98U,0x71374491U,0xb5c0fbcfU,0xe9b5dba5U,0x3956c25bU,0x59f111f1U,0x923f82a4U,0xab1c5ed5U,
    0xd807aa98U,0x12835b01U,0x243185beU,0x550c7dc3U,0x72be5d74U,0x80deb1feU,0x9bdc06a7U,0xc19bf174U,
    0xe49b69c1U,0xefbe4786U,0x0fc19dc6U,0x240ca1ccU,0x2de92c6fU,0x4a7484aaU,0x5cb0a9dcU,0x76f988daU,
    0x983e5152U,0xa831c66dU,0xb00327c8U,0xbf597fc7U,0xc6e00bf3U,0xd5a79147U,0x06ca6351U,0x14292967U,
    0x27b70a85U,0x2e1b2138U,0x4d2c6dfcU,0x53380d13U,0x650a7354U,0x766a0abbU,0x81c2c92eU,0x92722c85U,
    0xa2bfe8a1U,0xa81a664bU,0xc24b8b70U,0xc76c51a3U,0xd192e819U,0xd6990624U,0xf40e3585U,0x106aa070U,
    0x19a4c116U,0x1e376c08U,0x2748774cU,0x34b0bcb5U,0x391c0cb3U,0x4ed8aa4aU,0x5b9cca4fU,0x682e6ff3U,
    0x748f82eeU,0x78a5636fU,0x84c87814U,0x8cc70208U,0x90befffaU,0xa4506cebU,0xbef9a3f7U,0xc67178f2U
  };
  uint32_t w[64];
  for (size_t i = 0; i < 16; ++i) w[i] = load_be32(block + i * 4);
  for (size_t i = 16; i < 64; ++i) {
    uint32_t s0 = ror32(w[i-15],7) ^ ror32(w[i-15],18) ^ (w[i-15] >> 3);
    uint32_t s1 = ror32(w[i-2],17) ^ ror32(w[i-2],19) ^ (w[i-2] >> 10);
    w[i] = w[i-16] + s0 + w[i-7] + s1;
  }
  uint32_t a=state->h[0],b=state->h[1],c=state->h[2],d=state->h[3];
  uint32_t e=state->h[4],f=state->h[5],g=state->h[6],h=state->h[7];
  for (size_t i = 0; i < 64; ++i) {
    uint32_t s1=ror32(e,6)^ror32(e,11)^ror32(e,25), ch=(e&f)^((~e)&g);
    uint32_t t1=h+s1+ch+k[i]+w[i], s0=ror32(a,2)^ror32(a,13)^ror32(a,22), maj=(a&b)^(a&c)^(b&c);
    h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+s0+maj;
  }
  state->h[0]+=a;state->h[1]+=b;state->h[2]+=c;state->h[3]+=d;
  state->h[4]+=e;state->h[5]+=f;state->h[6]+=g;state->h[7]+=h;
}

static void sha256_init(struct sha256_state *state) {
  static const uint32_t initial[8] = {0x6a09e667U,0xbb67ae85U,0x3c6ef372U,0xa54ff53aU,0x510e527fU,0x9b05688cU,0x1f83d9abU,0x5be0cd19U};
  memcpy(state->h, initial, sizeof(initial)); state->bytes=0; state->used=0;
}

static void sha256_update(struct sha256_state *state, const void *input, size_t length) {
  const unsigned char *p = input; state->bytes += length;
  while (length != 0) {
    size_t take = 64 - state->used; if (take > length) take = length;
    memcpy(state->block + state->used, p, take); state->used += take; p += take; length -= take;
    if (state->used == 64) { sha256_compress(state, state->block); state->used = 0; }
  }
}

static void sha256_final(struct sha256_state *state, unsigned char out[32]) {
  uint64_t bits = state->bytes * 8U;
  state->block[state->used++] = 0x80;
  if (state->used > 56) { while (state->used < 64) state->block[state->used++] = 0; sha256_compress(state,state->block); state->used=0; }
  while (state->used < 56) state->block[state->used++] = 0;
  for (unsigned i=0;i<8;++i) state->block[63-i]=(unsigned char)(bits>>(i*8));
  sha256_compress(state,state->block);
  for (size_t i=0;i<8;++i) store_be32(out+i*4,state->h[i]);
}

struct sha1_state { uint32_t h[5]; uint64_t bytes; unsigned char block[64]; size_t used; };

static uint32_t rol32(uint32_t value, unsigned count) { return (value << count) | (value >> (32U-count)); }

static void sha1_compress(struct sha1_state *s, const unsigned char block[64]) {
  uint32_t w[80]; for(size_t i=0;i<16;++i) w[i]=load_be32(block+i*4);
  for(size_t i=16;i<80;++i) w[i]=rol32(w[i-3]^w[i-8]^w[i-14]^w[i-16],1);
  uint32_t a=s->h[0],b=s->h[1],c=s->h[2],d=s->h[3],e=s->h[4];
  for(size_t i=0;i<80;++i){ uint32_t f,k;
    if(i<20){f=(b&c)|((~b)&d);k=0x5a827999U;}else if(i<40){f=b^c^d;k=0x6ed9eba1U;}
    else if(i<60){f=(b&c)|(b&d)|(c&d);k=0x8f1bbcdcU;}else{f=b^c^d;k=0xca62c1d6U;}
    uint32_t t=rol32(a,5)+f+e+k+w[i];e=d;d=c;c=rol32(b,30);b=a;a=t;
  }
  s->h[0]+=a;s->h[1]+=b;s->h[2]+=c;s->h[3]+=d;s->h[4]+=e;
}

static void sha1_init(struct sha1_state *s){s->h[0]=0x67452301U;s->h[1]=0xefcdab89U;s->h[2]=0x98badcfeU;s->h[3]=0x10325476U;s->h[4]=0xc3d2e1f0U;s->bytes=0;s->used=0;}
static void sha1_update(struct sha1_state *s,const void *input,size_t length){const unsigned char*p=input;s->bytes+=length;while(length){size_t take=64-s->used;if(take>length)take=length;memcpy(s->block+s->used,p,take);s->used+=take;p+=take;length-=take;if(s->used==64){sha1_compress(s,s->block);s->used=0;}}}
static void sha1_final(struct sha1_state*s,unsigned char out[20]){uint64_t bits=s->bytes*8U;s->block[s->used++]=0x80;if(s->used>56){while(s->used<64)s->block[s->used++]=0;sha1_compress(s,s->block);s->used=0;}while(s->used<56)s->block[s->used++]=0;for(unsigned i=0;i<8;++i)s->block[63-i]=(unsigned char)(bits>>(i*8));sha1_compress(s,s->block);for(size_t i=0;i<5;++i)store_be32(out+i*4,s->h[i]);}

static int hex_value(unsigned char c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  return -1;
}

static bool parse_hex(const char *text, size_t chars, unsigned char *out) {
  if ((chars & 1U) != 0) return false;
  for (size_t i=0;i<chars/2;++i) { int hi=hex_value((unsigned char)text[i*2]),lo=hex_value((unsigned char)text[i*2+1]); if(hi<0||lo<0)return false; out[i]=(unsigned char)((hi<<4)|lo); }
  return true;
}

static void hex_encode(const unsigned char *bytes, size_t count, char *out) {
  static const char digits[]="0123456789abcdef";
  for(size_t i=0;i<count;++i){out[i*2]=digits[bytes[i]>>4];out[i*2+1]=digits[bytes[i]&15];}out[count*2]='\0';
}

static void wire_put_u32(unsigned char *out,uint32_t value){out[0]=(unsigned char)(value>>24);out[1]=(unsigned char)(value>>16);out[2]=(unsigned char)(value>>8);out[3]=(unsigned char)value;}
static void wire_put_u64(unsigned char *out,uint64_t value){for(unsigned i=0;i<8;++i)out[7-i]=(unsigned char)(value>>(i*8));}
static uint32_t wire_get_u32(const unsigned char *in){return ((uint32_t)in[0]<<24)|((uint32_t)in[1]<<16)|((uint32_t)in[2]<<8)|in[3];}
static uint64_t wire_get_u64(const unsigned char *in){uint64_t value=0;for(unsigned i=0;i<8;++i)value=(value<<8)|in[i];return value;}
static void encode_be16(unsigned char out[2],uint16_t value);
static bool canonical_u64_text(const char*text,uint64_t*out){if(!text||!out||!*text||(text[0]=='0'&&text[1]))return false;uint64_t value=0;for(const unsigned char*p=(const unsigned char*)text;*p;++p){if(*p<'0'||*p>'9')return false;unsigned digit=(unsigned)(*p-'0');if(value>(UINT64_MAX-digit)/10U)return false;value=value*10U+digit;}*out=value;return true;}

