  if(tb_printf(out,"{\"anchorIdentity\":{\"byteLength\":\"%llu\",\"sha256\":\"%s\",\"source\":\"OUT_OF_BAND_TRUSTED_INVOKER_FIXED_FD\"},\"bootId\":\"%s\",\"childExecutionProjectionSha256\":\"%s\",\"externalExpectedSchemas\":",(unsigned long long)anchor->anchor_length,anchor->anchor_sha,anchor->boot_id,child_projection)!=0||tb_schema_group(out,bootstrap)!=0||tb_puts(out,",\"fd3\":")!=0||tb_fd3_identity(out,fd3_ofd,peer_identity)!=0||tb_puts(out,",\"fd4\":")!=0||tb_fd4_identity(out,bundle)!=0||tb_puts(out,",\"invokerRequestSha256\":")!=0||tb_json_string(out,anchor->invoker_request_sha)!=0||tb_puts(out,",\"ledgerSnapshot\":")!=0||tb_ledger_snapshot(out)!=0||tb_printf(out,",\"oneUseCapabilityDigest\":\"%s\",\"package\":",anchor->capability)!=0||tb_package_binding(out)!=0||tb_printf(out,",\"requestNonce\":\"%s\",\"runId\":\"%s\",\"schema\":\"iat-b3-post-checkpoint-prelaunch-supervisor-projection-request-prebinding/v1\",\"sessionId\":\"%s\",\"supervisorReleaseId\":\"%s\",\"window\":{\"armedMonotonicNs\":\"%s\",\"operationDeadlineMonotonicNs\":\"%s\",\"teardownDeadlineMonotonicNs\":\"%s\"}}",anchor->request_nonce,anchor->run_id,anchor->session_id,anchor->release_id,anchor->armed_ns,anchor->operation_deadline_ns,anchor->teardown_deadline_ns)!=0){tb_free(out);return -1;}
