  struct timespec now;if(clock_gettime(CLOCK_MONOTONIC,&now)!=0)return -1;uint64_t observed=(uint64_t)now.tv_sec*UINT64_C(1000000000)+(uint64_t)now.tv_nsec,armed=strtoull(anchor->armed_ns,NULL,10),deadline=strtoull(anchor->operation_deadline_ns,NULL,10);if(observed<armed||observed>deadline||deadline-armed>BPS05_OPERATION_NS)return -1;
